import { describe, it, before, after } from "node:test";
import * as assert from "node:assert";
import * as fs from "fs";
import * as path from "path";
import * as os from "os";
import { jaccardSimilarity } from "../utils/mathUtils.js";

const TMP_DIR = path.join(os.tmpdir(), "codeatlas-e2e-" + Date.now());
const PROJECT_DIR = path.join(TMP_DIR, "test-project");

describe("E2E — 5 new features (manage_adr, get_code_snippet, index_coverage, detect_code_similarities, export_team_artifact)", () => {
  before(async () => {
    // Create test project with some source files
    fs.mkdirSync(path.join(PROJECT_DIR, "src"), { recursive: true });
    fs.mkdirSync(path.join(PROJECT_DIR, "utils"), { recursive: true });

    // Helper file
    fs.writeFileSync(path.join(PROJECT_DIR, "src", "userService.ts"), `
export class UserService {
  async getUser(id: string) {
    const user = await this.findUser(id);
    return user;
  }

  async findUser(id: string) {
    return { id, name: "Test" };
  }
}
`);

    // Similar file (for similarity detection)
    fs.writeFileSync(path.join(PROJECT_DIR, "utils", "helper.ts"), `
export class HelperService {
  async getHelper(id: string) {
    const item = await this.findHelper(id);
    return item;
  }

  async findHelper(id: string) {
    return { id, name: "Helper" };
  }
}
`);

    // Git init to make it a "real" project
    try { fs.mkdirSync(path.join(PROJECT_DIR, ".git")); } catch {}
    fs.writeFileSync(path.join(PROJECT_DIR, "package.json"), JSON.stringify({ name: "test-project", version: "1.0.0" }));
    fs.writeFileSync(path.join(PROJECT_DIR, ".gitignore"), "node_modules/\n");
    fs.writeFileSync(path.join(PROJECT_DIR, "README.md"), "# Test Project\n");

    // Mock analysis data
    const analysis = {
      graph: {
        nodes: [
          { id: "UserService", label: "UserService", type: "class", filePath: "src/userService.ts", line: 2 },
          { id: "getUser", label: "getUser", type: "function", filePath: "src/userService.ts", line: 3 },
          { id: "findUser", label: "findUser", type: "function", filePath: "src/userService.ts", line: 8 },
          { id: "HelperService", label: "HelperService", type: "class", filePath: "utils/helper.ts", line: 2 },
          { id: "getHelper", label: "getHelper", type: "function", filePath: "utils/helper.ts", line: 3 },
          { id: "findHelper", label: "findHelper", type: "function", filePath: "utils/helper.ts", line: 8 },
        ],
        links: [
          { source: "UserService", target: "getUser", type: "contains" },
          { source: "getUser", target: "findUser", type: "call" },
          { source: "HelperService", target: "getHelper", type: "contains" },
          { source: "getHelper", target: "findHelper", type: "call" },
        ],
      },
      insights: [],
      entityCounts: { modules: 2, functions: 4, classes: 2, dependencies: 2, circularDeps: 0 },
      totalFilesAnalyzed: 2,
      totalFilesSkipped: 0,
    };

    // Save analysis
    fs.mkdirSync(path.join(TMP_DIR, ".codeatlas"), { recursive: true });
    fs.writeFileSync(path.join(TMP_DIR, ".codeatlas", "analysis.json"), JSON.stringify(analysis));

    // Mock analysis index
    if (!process.env.CODEATLAS_ANALYSIS_DIR) {
      process.env.CODEATLAS_ANALYSIS_DIR = TMP_DIR;
    }

    // Import and mock the projectService module by setting env
    const { inMemoryAnalysisCache } = await import("./projectService.js");
    inMemoryAnalysisCache.set(PROJECT_DIR, analysis);
  });

  after(() => {
    try { fs.rmSync(TMP_DIR, { recursive: true, force: true }); } catch { /* skip */ }
    delete process.env.CODEATLAS_ANALYSIS_DIR;
  });

  // ═══════════ ADR Service ═══════════
  describe("1. manage_adr — Architecture Decision Records", () => {
    it("creates and reads ADRs via service", async () => {
      const { saveADR, getADR } = await import("./adrService.js");
      saveADR({ id: "e2e-adr-1", title: "Use TypeScript", status: "accepted", context: "Need types", decision: "Adopt TS", consequences: "Slower build", project: "e2e-test", date: "2024-07-01" });
      const adr = getADR("e2e-adr-1", "e2e-test");
      assert.ok(adr);
      assert.strictEqual(adr!.title, "Use TypeScript");
      assert.strictEqual(adr!.status, "accepted");
    });

    it("lists ADRs sorted newest-first", async () => {
      const { saveADR, listADRs } = await import("./adrService.js");
      saveADR({ id: "e2e-adr-2", title: "Old", status: "proposed", context: "", decision: "A", consequences: "", project: "e2e-test", date: "2023-01-01" });
      saveADR({ id: "e2e-adr-3", title: "New", status: "accepted", context: "", decision: "B", consequences: "", project: "e2e-test", date: "2024-07-15" });
      const all = await listADRs("e2e-test");
      assert.ok(all.length >= 3);
      assert.strictEqual(all[0].date, "2024-07-15");
    });

    it("updates ADR status and supersedes", async () => {
      const { saveADR, getADR, listADRs } = await import("./adrService.js");
      saveADR({ id: "e2e-adr-sup", title: "Superseded Dec", status: "accepted", context: "", decision: "X", consequences: "", project: "e2e-test", date: "2024-01-01" });
      const adr = getADR("e2e-adr-sup", "e2e-test")!;
      adr.status = "superseded";
      adr.supersededBy = "e2e-adr-new";
      const { saveADR: save2 } = await import("./adrService.js");
      save2(adr);
      const updated = getADR("e2e-adr-sup", "e2e-test")!;
      assert.strictEqual(updated.status, "superseded");
      assert.strictEqual(updated.supersededBy, "e2e-adr-new");
    });

    it("deletes ADRs", async () => {
      const { saveADR, getADR, deleteADR } = await import("./adrService.js");
      saveADR({ id: "e2e-adr-del", title: "Temp", status: "proposed", context: "", decision: "D", consequences: "", project: "e2e-test", date: "2024-01-01" });
      assert.ok(getADR("e2e-adr-del", "e2e-test"));
      deleteADR("e2e-adr-del", "e2e-test");
      assert.strictEqual(getADR("e2e-adr-del", "e2e-test"), null);
    });
  });

  // ═══════════ Code Snippet ═══════════
  describe("2. get_code_snippet — source code by symbol", () => {
    it("finds and reads code for a symbol", async () => {
      const { inMemoryAnalysisCache } = await import("./projectService.js");
      // We already set up cache in before()
      const cache = inMemoryAnalysisCache.get(PROJECT_DIR);
      assert.ok(cache, "Analysis should be in cache");

      // Find symbol in analysis
      const node = cache!.graph.nodes.find((n: { label: string }) => n.label === "getUser");
      assert.ok(node, "getUser node should exist");
      assert.strictEqual(node!.type, "function");
      assert.ok(node!.filePath);
    });

    it("reads actual file contents", async () => {
      const filePath = path.join(PROJECT_DIR, "src", "userService.ts");
      const content = fs.readFileSync(filePath, "utf-8");
      assert.ok(content.includes("class UserService"));
      assert.ok(content.includes("getUser"));
    });
  });

  // ═══════════ Index Coverage ═══════════
  describe("3. index_coverage — coverage report", () => {
    it("detects entity types in analysis", async () => {
      const { inMemoryAnalysisCache } = await import("./projectService.js");
      const cache = inMemoryAnalysisCache.get(PROJECT_DIR);
      const types: Record<string, number> = {};
      for (const n of cache!.graph.nodes as Array<{ type: string }>) {
        types[n.type] = (types[n.type] || 0) + 1;
      }
      assert.strictEqual(types["function"], 4);
      assert.strictEqual(types["class"], 2);
    });

    it("calculates coverage percentage", async () => {
      const { inMemoryAnalysisCache } = await import("./projectService.js");
      const cache = inMemoryAnalysisCache.get(PROJECT_DIR);
      const nodes = cache!.graph.nodes as Array<{ id: string; filePath?: string }>;
      const total = nodes.filter(n => !n.id.startsWith("external:")).length;
      const withFile = nodes.filter(n => n.filePath).length;
      const pct = Math.round((withFile / total) * 100);
      assert.ok(pct >= 80, `Coverage should be >= 80%, got ${pct}%`);
    });

    it("identifies orphan nodes (no connections)", async () => {
      const { inMemoryAnalysisCache } = await import("./projectService.js");
      const cache = inMemoryAnalysisCache.get(PROJECT_DIR);
      const nodes = cache!.graph.nodes as Array<{ id: string }>;
      const links = cache!.graph.links as Array<{ source: string; target: string }>;
      const connectedIds = new Set<string>();
      for (const l of links) { connectedIds.add(l.source); connectedIds.add(l.target); }
      const orphans = nodes.filter(n => !connectedIds.has(n.id));
      // Our mock has all connected
      assert.strictEqual(orphans.length, 0);
    });
  });

  // ═══════════ Code Similarity ═══════════
  describe("4. detect_code_similarities — Jaccard similarity", () => {
    const tokenize = (s: string) => {
      const tokens = new Set<string>();
      const re = /[a-zA-Z_$][a-zA-Z0-9_$]*/g;
      let m;
      while ((m = re.exec(s)) !== null) tokens.add(m[0].toLowerCase());
      return tokens;
    };

    const jaccardSimilarity = (setA: Set<string>, setB: Set<string>) => {
      let intersectionSize = 0;
      const [smaller, larger] = setA.size < setB.size ? [setA, setB] : [setB, setA];
      for (const t of smaller) {
        if (larger.has(t)) intersectionSize++;
      }
      const unionSize = setA.size + setB.size - intersectionSize;
      return { intersectionSize, unionSize, similarity: unionSize === 0 ? 0 : intersectionSize / unionSize };
    };

    it("computes Jaccard token similarity between two files", async () => {
      const contentA = fs.readFileSync(path.join(PROJECT_DIR, "src", "userService.ts"), "utf-8");
      const contentB = fs.readFileSync(path.join(PROJECT_DIR, "utils", "helper.ts"), "utf-8");

      const tokensA = tokenize(contentA);
      const tokensB = tokenize(contentB);

      const { similarity } = jaccardSimilarity(tokensA, tokensB);
      // These two files are very similar (same structure, different names)
      assert.ok(similarity >= 0.5, `Similarity should be >= 0.5, got ${similarity}`);
    });

    it("returns 0 for completely different tokens", async () => {
      const tokensA = tokenize("abc def ghi xyz");
      const tokensB = tokenize("xxx yyy zzz");
      const { intersectionSize, unionSize } = jaccardSimilarity(tokensA, tokensB);
      assert.strictEqual(intersectionSize, 0);
      assert.strictEqual(unionSize, 7);
    });
  });

  // ═══════════ Export Artifact ═══════════
  describe("5. export_team_artifact — snapshot export", () => {
    it("exports summary to .codeatlas/ directory", async () => {
      const artifactDir = path.join(PROJECT_DIR, ".codeatlas");
      fs.mkdirSync(artifactDir, { recursive: true });

      const { inMemoryAnalysisCache } = await import("./projectService.js");
      const cache = inMemoryAnalysisCache.get(PROJECT_DIR);
      assert.ok(cache, "Analysis must be in cache for export");

      // Simulate export
      // ⚡ Bolt Optimization: Replace O(N*L) array finds inside map with O(1) Map lookups and early exit loop
      const nodeLabelMap = new Map<string, string>();
      for (const n of cache!.graph.nodes) {
        nodeLabelMap.set(n.id, n.label);
      }

      const callGraph: Array<{ from: string; to: string }> = [];
      for (const l of cache!.graph.links) {
        if (l.type === "call") {
          callGraph.push({
            from: nodeLabelMap.get(l.source) || l.source,
            to: nodeLabelMap.get(l.target) || l.target,
          });
          if (callGraph.length >= 500) break;
        }
      }

      // ⚡ Bolt Optimization: Replace 3 chained .filter().map() passes with a single O(N) pass
      const modules: Array<{ id: string; name: string; file?: string }> = [];
      const classes: Array<{ id: string; name: string; file?: string; line?: number }> = [];
      const functions: Array<{ id: string; name: string; file?: string; line?: number }> = [];

      for (const n of cache!.graph.nodes) {
        if (n.type === "module" || n.type === "class") modules.push({ id: n.id, name: n.label, file: n.filePath });
        if (n.type === "class") classes.push({ id: n.id, name: n.label, file: n.filePath, line: n.line });
        if (n.type === "function") functions.push({ id: n.id, name: n.label, file: n.filePath, line: n.line });
      }

      const summary = {
        version: 1,
        exportedAt: new Date().toISOString(),
        project: "test-project",
        stats: { modules: 2, functions: 4, classes: 2, dependencies: 2, circularDeps: 0, deadCode: 0 },
        modules,
        classes,
        functions,
        callGraph,
      };

      const outPath = path.join(artifactDir, "artifact-summary.json");
      fs.writeFileSync(outPath, JSON.stringify(summary, null, 2));
      assert.ok(fs.existsSync(outPath));

      const parsed = JSON.parse(fs.readFileSync(outPath, "utf-8"));
      assert.strictEqual(parsed.project, "test-project");
      assert.strictEqual(parsed.classes.length, 2);
      assert.strictEqual(parsed.functions.length, 4);
    });
  });
});

import * as fs from "fs";
import * as path from "path";
import * as https from "https";
import * as os from "os";
import { getHomePath } from "../utils/pathUtils.js";
import { CodeAnalyzer } from "../analyzer/parser.js";
import { AnalysisResult } from "../analyzer/types.js";
import { authStorage } from "../context.js";

export interface AnalysisResultLocal extends AnalysisResult {
  stats?: { files: number; functions: number; classes: number; dependencies: number; circularDeps: number; deadCode: number };
}

export const fsWrapper = {
  existsSync: (p: string) => fs.existsSync(p),
  readFileSync: (p: string, encoding: "utf8") => fs.readFileSync(p, encoding),
  readdirSync: (p: string) => fs.readdirSync(p)
};

/**
 * Validates if a target path is safely contained within an authorized workspace path.
 * Resolves symlinks and normalizes paths before comparison to prevent path traversal.
 */
export function isPathInAuthorizedProjects(targetPath: string, authorizedProjects: { dir: string }[]): boolean {
  let resolvedTarget: string;
  try {
    resolvedTarget = fs.realpathSync(path.resolve(targetPath));
  } catch (err) {
    return false;
  }

  return authorizedProjects.some(p => {
    try {
      const resolvedAuth = fs.realpathSync(path.resolve(p.dir));
      return resolvedTarget === resolvedAuth || resolvedTarget.startsWith(resolvedAuth + path.sep);
    } catch {
      return false;
    }
  });
}

/** Unified stats helper */
export function getStats(analysis: AnalysisResultLocal) {
  const ec = analysis.entityCounts;
  const st = analysis.stats;
  return {
    files: st?.files ?? analysis.totalFilesAnalyzed ?? ec?.modules ?? 0,
    modules: ec?.modules ?? st?.files ?? analysis.totalFilesAnalyzed ?? 0,
    functions: ec?.functions ?? st?.functions ?? 0,
    classes: ec?.classes ?? st?.classes ?? 0,
    dependencies: ec?.dependencies ?? st?.dependencies ?? 0,
    circularDeps: ec?.circularDeps ?? st?.circularDeps ?? 0,
    deadCode: ec?.deadCode ?? st?.deadCode ?? 0,
  };
}

function findDirMatchingNormalized(normalized: string): string | null {
  if (!/^[a-zA-Z0-9_]+$/.test(normalized)) {
    return null;
  }

  const directPath = "/" + normalized.replace(/_/g, "/");
  if (fsWrapper.existsSync(directPath)) {
    return directPath;
  }

  const parts = normalized.split("_").filter(Boolean);
  if (parts.length === 0) return null;

  let lowerParts: string[] | null = null;

  let currentPath = "/";
  for (let i = 0; i < parts.length; i++) {
    if (!fsWrapper.existsSync(currentPath)) return null;

    try {
      const files = fsWrapper.readdirSync(currentPath);
      let matchedEntry = "";
      let matchedPartCount = 0;
      let matchedIsExactCase = false;

      for (const file of files) {
        const normFile = file.replace(/[^a-zA-Z0-9]/g, "_");
        const normFileParts = normFile.split("_").filter(Boolean);
        if (normFileParts.length === 0) continue;

        let normFilePartsLower: string[] | null = null;

        let match = true;
        let isExactCase = true;
        for (let j = 0; j < normFileParts.length; j++) {
          if (i + j >= parts.length) {
            match = false;
            break;
          }
          const partA = parts[i + j];
          const partB = normFileParts[j];

          if (partA !== partB) {
            isExactCase = false;

            // Lazy-compute lowercase arrays to avoid allocations on exact matches
            if (normFilePartsLower === null) {
              normFilePartsLower = normFileParts.map(p => p.toLowerCase());
            }
            if (lowerParts === null) {
              lowerParts = parts.map(p => p.toLowerCase());
            }

            // Avoid .toLowerCase() allocation during case-insensitive comparison
            if (lowerParts[i + j] !== normFilePartsLower[j]) {
              match = false;
              break;
            }
          }
        }

        if (match) {
          if (normFileParts.length > matchedPartCount || (normFileParts.length === matchedPartCount && isExactCase && !matchedIsExactCase)) {
            matchedEntry = file;
            matchedPartCount = normFileParts.length;
            matchedIsExactCase = isExactCase;
          }
        }
      }

      if (matchedEntry) {
        currentPath = path.join(currentPath, matchedEntry);
        i += matchedPartCount - 1;
      } else {
        currentPath = path.join(currentPath, parts[i]);
      }
    } catch {
      return null;
    }
  }

  if (fsWrapper.existsSync(currentPath)) {
    return currentPath;
  }
  return null;
}

/**
 * Discovers workspace directory by traversing ancestor processes via /proc.
 * @param startPid - Process ID to start traversal from (defaults to current process)
 * @returns Resolved workspace directory path, or null if not found or on unsupported platforms
 * @platform Linux only - requires /proc filesystem
 */
export function getWorkspaceFromAncestors(startPid: number = process.pid): string | null {
  try {
    // 1. Build a map of PPID -> children PIDs by scanning /proc once.
    // This allows us to inspect siblings of processes in the ancestor chain.
    const ppidToChildren = new Map<number, number[]>();
    if (fsWrapper.existsSync('/proc')) {
      const files = fsWrapper.readdirSync('/proc');
      for (const file of files) {
        if (/^\d+$/.test(file)) {
          const pid = parseInt(file, 10);
          const statusPath = `/proc/${pid}/status`;
          try {
            if (fsWrapper.existsSync(statusPath)) {
              const statusContent = fsWrapper.readFileSync(statusPath, 'utf8');
              const ppidMatch = statusContent.match(/^PPid:\s+(\d+)/m);
              if (ppidMatch) {
                const ppid = parseInt(ppidMatch[1], 10);
                if (!ppidToChildren.has(ppid)) {
                  ppidToChildren.set(ppid, []);
                }
                ppidToChildren.get(ppid)!.push(pid);
              }
            }
          } catch {
            // Ignore access errors on individual processes
          }
        }
      }
    }

    // 2. Traverse up the ancestor chain
    let currentPid = startPid;
    let iterations = 0;
    while (currentPid > 1 && iterations < 100) {
      iterations++;
      const statusPath = `/proc/${currentPid}/status`;
      if (!fsWrapper.existsSync(statusPath)) break;
      const statusContent = fsWrapper.readFileSync(statusPath, 'utf8');
      const ppidMatch = statusContent.match(/^PPid:\s+(\d+)/m);
      if (!ppidMatch) break;
      const ppid = parseInt(ppidMatch[1], 10);
      if (ppid <= 1 || ppid === currentPid) break;

      // First check: does the parent process itself have the workspace ID?
      const parentCmdlinePath = `/proc/${ppid}/cmdline`;
      if (fsWrapper.existsSync(parentCmdlinePath)) {
        const cmdline = fsWrapper.readFileSync(parentCmdlinePath, 'utf8');
        const args = cmdline.split('\0');
        const workspaceIdIndex = args.indexOf('--workspace_id');
        if (workspaceIdIndex !== -1 && workspaceIdIndex + 1 < args.length) {
          const workspaceId = args[workspaceIdIndex + 1];
          if (workspaceId.startsWith('file_')) {
            const normalized = workspaceId.substring(5);
            const dir = findDirMatchingNormalized(normalized);
            if (dir) return dir;
          }
        }
      }

      // Second check: check all siblings (other children of ppid)
      const siblings = ppidToChildren.get(ppid) || [];
      for (const siblingPid of siblings) {
        if (siblingPid === currentPid) continue; // Skip self
        const cmdlinePath = `/proc/${siblingPid}/cmdline`;
        if (fsWrapper.existsSync(cmdlinePath)) {
          const cmdline = fsWrapper.readFileSync(cmdlinePath, 'utf8');
          const args = cmdline.split('\0');
          const workspaceIdIndex = args.indexOf('--workspace_id');
          if (workspaceIdIndex !== -1 && workspaceIdIndex + 1 < args.length) {
            const workspaceId = args[workspaceIdIndex + 1];
            if (workspaceId.startsWith('file_')) {
              const normalized = workspaceId.substring(5);
              const dir = findDirMatchingNormalized(normalized);
              if (dir) return dir;
            }
          }
        }
      }

      currentPid = ppid;
    }
  } catch {
    // Ignore and fallback
  }
  return null;
}


export function registerProject(dir: string): void {
  try {
    const homeDir = getHomePath();
    const configDir = path.join(homeDir, ".codeatlas");
    if (!fs.existsSync(configDir)) {
      fs.mkdirSync(configDir, { recursive: true });
    }
    const regPath = path.join(configDir, "registered_projects.json");
    let projects: string[] = [];
    if (fs.existsSync(regPath)) {
      try {
        const data = fs.readFileSync(regPath, "utf-8");
        projects = JSON.parse(data);
      } catch {
        projects = [];
      }
    }
    if (!Array.isArray(projects)) {
      projects = [];
    }
    const absPath = path.resolve(dir);
    if (isSystemIdeDirectory(absPath)) {
      return;
    }
    if (!projects.includes(absPath)) {
      projects.push(absPath);
      fs.writeFileSync(regPath, JSON.stringify(projects, null, 2));
      console.error(`[Project-Registry] 📝 Registered new project: ${absPath}`);
    }
  } catch (err) {
    console.error(`[Project-Registry] ❌ Failed to register project: ${err}`);
  }
}

let onProjectLoadedCallback: ((dir: string) => void) | null = null;
export function registerOnProjectLoaded(cb: (dir: string) => void) {
  onProjectLoadedCallback = cb;
}

/**
 * LRU cache that evicts oldest entries when exceeding maxSize.
 * On eviction, also cleans up the corresponding CodeAnalyzer instance.
 */
class LRUCache<V> {
  private map = new Map<string, V>();
  private readonly maxSize: number;
  private evictionLog: string;

  constructor(maxSize: number, name = "cache") {
    this.maxSize = maxSize;
    this.evictionLog = `[${name}]`;
  }

  has(key: string): boolean {
    return this.map.has(key);
  }

  get(key: string): V | undefined {
    if (!this.map.has(key)) return undefined;
    // Move to end (most recently used)
    const value = this.map.get(key)!;
    this.map.delete(key);
    this.map.set(key, value);
    return value;
  }

  set(key: string, value: V): this {
    this.map.delete(key); // Remove if exists, re-add at end
    this.map.set(key, value);
    this.evict();
    return this;
  }

  delete(key: string): boolean {
    return this.map.delete(key);
  }

  get size(): number {
    return this.map.size;
  }

  keys(): IterableIterator<string> {
    return this.map.keys();
  }

  private evict() {
    while (this.map.size > this.maxSize) {
      const oldestKey = this.map.keys().next().value;
      if (oldestKey !== undefined) {
        this.map.delete(oldestKey);
        // Also cleanup the CodeAnalyzer instance to free memory
        const hadAnalyzer = analyzerInstances.delete(oldestKey);
        console.error(`${this.evictionLog} 🗑️ Evicted cache for: ${oldestKey}${hadAnalyzer ? ' (analyzer also freed)' : ''}`);
      }
    }
  }

  [Symbol.iterator](): IterableIterator<[string, V]> {
    return this.map[Symbol.iterator]();
  }
}

export const inMemoryAnalysisCache = new LRUCache<any>(3, "Cache");

export const analyzerInstances = new LRUCache<CodeAnalyzer>(5, "Analyzer");

export function getOpenIdeForDir(dir: string): string | null {
  try {
    const absPath = path.resolve(dir.trim());
    if (!fs.existsSync('/proc')) return null;
    const files = fs.readdirSync('/proc');
    // Safety: only scan up to 500 process entries to prevent abuse.
    // Optimized filtering with an early exit to avoid scanning and evaluating
    // unnecessary entries in large directories.
    const pidEntries: string[] = [];
    const pidRegex = /^\d+$/;
    for (const f of files) {
      if (pidRegex.test(f)) {
        pidEntries.push(f);
        if (pidEntries.length >= 500) break;
      }
    }
    for (const file of pidEntries) {
      const pid = file;
      const cmdlinePath = `/proc/${pid}/cmdline`;
      try {
          if (fs.existsSync(cmdlinePath)) {
            const cmdline = fs.readFileSync(cmdlinePath, 'utf8');
            const args = cmdline.split('\0').filter(Boolean);
            if (args.length === 0) continue;

            const hasDirArg = args.some(arg => {
              try {
                return path.resolve(arg) === absPath;
              } catch {
                return false;
              }
            });

            if (hasDirArg) {
              const exePath = args[0].toLowerCase();
              const ideKeywords = ['code', 'vscode', 'cursor', 'windsurf', 'intellij', 'webstorm', 'phpstorm', 'idea', 'eclipse', 'sublime', 'gemini-cli'];
              for (const keyword of ideKeywords) {
                if (exePath.includes(keyword)) {
                  return path.basename(args[0]);
                }
              }
            }
          }
        } catch {
          // ignore
        }
    }
  } catch {
    // ignore
  }
  return null;
}

export function isProjectDirectory(dir: string): boolean {
  if (isSystemIdeDirectory(dir)) {
    return false;
  }
  try {
    if (!fs.existsSync(dir) || !fs.statSync(dir).isDirectory()) {
      return false;
    }
    const gitPath = path.join(dir, ".git");
    if (fs.existsSync(gitPath)) {
      return true;
    }
    const codeatlasPath = path.join(dir, ".codeatlas");
    if (fs.existsSync(codeatlasPath)) {
      return true;
    }
    const openIde = getOpenIdeForDir(dir);
    if (openIde) {
      console.error(`[Project-Discovery] 🖥️ Project ${dir} is active in IDE: ${openIde}`);
      return true;
    }
    return false;
  } catch {
    return false;
  }
}

export async function isProjectDirectoryAsync(dir: string): Promise<boolean> {
