export function writeFileSyncNoFollow(filePath: string, content: string, mode: number = 0o600): void {
  const fd = fs.openSync(
    filePath,
    fs.constants.O_CREAT |   // Create file if it doesn't exist
    fs.constants.O_WRONLY |  // Open for writing
    fs.constants.O_TRUNC |   // Truncate file content if it exists
    fs.constants.O_NOFOLLOW, // Prevent symlink following
    mode
  );
  try {
    fs.writeFileSync(fd, content);
  } finally {
    fs.closeSync(fd);
  }
}

import * as fs from 'fs';
import * as path from 'path';
import { parse } from '@typescript-eslint/typescript-estree';
import ignore from 'ignore';
import { GraphData, GraphNode, GraphLink, AnalysisResult, AIInsight, AnalysisManifest, FolderInfo, ChunkData, CrossChunkLinks } from './types.js';
import { PythonParser } from './pythonParser.js';
import { PhpParser } from './phpParser.js';
import { binarySearchClosestPrecedingClass, ClassReference } from '../utils/arrayUtils.js';

export class CodeAnalyzer {
  private workspaceRoot: string;
  private nodes: Map<string, GraphNode> = new Map();
  private links: GraphLink[] = [];
  private readonly maxFiles: number;
  private readonly excludedDirectories: string[];
  private readonly excludedFiles: string[];
  private readonly fileExtensions: string[];

  private dirCache = new Map<string, Map<string, fs.Dirent> | null>();

  private ignoreFilter: ReturnType<typeof ignore> | null = null;

  constructor(
    workspaceRoot: string,
    maxFiles: number = 5000,
    excludedDirectories: string[] = ['node_modules', 'dist', 'out', '.git', '__pycache__', '.venv', 'venv', 'env', '.env', 'vendor', 'build', '.tox', '.mypy_cache', '.pytest_cache', 'coverage', '.next', '.nuxt',
      // Common user home subdirectories — prevent accidental full-home scans
      'Downloads', 'Desktop', 'Documents', 'Pictures', 'Music', 'Videos', 'snap', 'go', 'AppData', 'Applications', 'Public', 'Templates'],
    fileExtensions: string[] = ['.ts', '.tsx', '.js', '.jsx', '.py', '.php'],
    excludedFiles: string[] = ['_ide_helper.php', '_ide_helper_models.php', '.phpstorm.meta.php']
  ) {
    this.workspaceRoot = workspaceRoot;
    this.maxFiles = maxFiles;
    this.excludedDirectories = excludedDirectories;
    this.excludedFiles = excludedFiles;
    this.fileExtensions = fileExtensions;
  }

  private getDirContents(dirPath: string): Map<string, fs.Dirent> | null {
    let contents = this.dirCache.get(dirPath);
    if (contents === undefined) {
      try {
        contents = new Map();
        const entries = fs.readdirSync(dirPath, { withFileTypes: true });
        for (const entry of entries) {
          contents.set(entry.name, entry);
        }
      } catch {
        contents = null;
      }
      this.dirCache.set(dirPath, contents);
    }
    return contents;
  }

  private getIgnoreFilter(): ReturnType<typeof ignore> {
    if (this.ignoreFilter) {
      return this.ignoreFilter;
    }
    const ig = ignore();
    // Excluded dirs/files will match relative paths correctly
    ig.add(this.excludedDirectories);
    ig.add(this.excludedFiles);

    const gitignorePath = path.join(this.workspaceRoot, '.gitignore');
    if (fs.existsSync(gitignorePath)) {
      try {
        const gitignoreContent = fs.readFileSync(gitignorePath, 'utf-8');
        ig.add(gitignoreContent);
      } catch (e) {
        console.warn(`[CodeAnalyzer] Failed to read .gitignore at ${gitignorePath}`, e);
      }
    }
    this.ignoreFilter = ig;
    return ig;
  }

  private isIgnored(absolutePath: string, isDirectory: boolean): boolean {
    const relPath = path.relative(this.workspaceRoot, absolutePath);
    if (!relPath || relPath === '.' || relPath.startsWith('..')) {
      return false;
    }
    let normalizedPath = relPath.replace(/\\/g, '/');
    if (isDirectory && !normalizedPath.endsWith('/')) {
      normalizedPath += '/';
    }
    return this.getIgnoreFilter().ignores(normalizedPath);
  }

  /**
   * Tracks all analyzed file paths.
   * Using Set to optimize addition, deletion, and lookup operations. Reduces O(N) operations
   * (e.g., .includes or .indexOf) to O(1) for large datasets. This is particularly impactful for environments
   * handling large datasets, where frequent mutations or membership checks may cause major performance costs.
   * The Set structure also inherently prevents duplicates, eliminating the need for manual uniqueness checks.
   */
  private allFiles: Set<string> = new Set<string>();

  /**
   * Tracks files that encountered transient IO errors (e.g. EACCES locks)
   * so they can be identified and potentially re-queued by the caller.
   */
  public transientErrors: Set<string> = new Set<string>();

  private reportInfo(message: string) {
    console.info(message);
  }

  private reportError(message: string) {
    console.error(message);
  }

  private reportWarning(message: string, stack?: string) {
    if (stack) {
      console.warn(message, stack);
    } else {
      console.warn(message);
    }
  }

  /**
   * Sanitizes paths for logging by replacing the workspace root with a placeholder
   * and normalizing directory separators.
   */
  private sanitizePath(absPath: string): string {
    if (!this.workspaceRoot) return absPath.replace(/\\/g, '/');

    // We cannot use string replace with regex characters dynamically without escaping,
    // but a safer approach is substring if it starts with the root.
    if (absPath.startsWith(this.workspaceRoot)) {
      return '[WORKSPACE]' + absPath.substring(this.workspaceRoot.length).replace(/\\/g, '/');
    }
    return absPath.replace(/\\/g, '/');
  }

  private handleFileError(err: unknown, absPath: string) {
    const error = err as NodeJS.ErrnoException;
    // Scrub absolute path using the unified sanitization logic
    const safeName = this.sanitizePath(absPath);
    if (error && error.code === 'ENOENT') {
      this.reportInfo(`[CodeAnalyzer] File not found (likely deleted): ${safeName}`);
    } else if (error && error.code === 'EACCES') {
      this.transientErrors.add(absPath);
      this.reportError(`[CodeAnalyzer][Security][FileAccess] Access denied to file: ${safeName}`);
    } else {
      this.transientErrors.add(absPath);
      const message = (error && error.message) || (error && error.code) || 'Unknown error';
      if (process.env.DEBUG === 'true') {
        this.reportWarning(`[CodeAnalyzer] Unexpected error accessing file ${safeName}: ${message}`, error?.stack ? this.sanitizePath(error.stack) : undefined);
      } else {
        this.reportWarning(`[CodeAnalyzer] Unexpected error accessing file ${safeName}: ${message}`);
      }
    }
  }
  private totalSkippedCount = 0;

  public async analyzeProject(onProgress?: (percent: number, done: number, total: number, currentFile?: string) => void): Promise<AnalysisResult> {
    this.dirCache.clear();
    this.nodes.clear();
    this.links = [];

    let files = this.getFiles(this.workspaceRoot);
    if (files.length > this.maxFiles) {
      console.warn(`[CodeAnalyzer] Workspace has ${files.length} files, which exceeds maxFiles (${this.maxFiles}). Truncating to ${this.maxFiles} files.`);
      files = files.slice(0, this.maxFiles);
    }

    // The files array is generated from getFiles traversing unique directories recursively,
    // so duplicates are naturally prevented. The map resolves paths, and the Set enforces uniqueness across edge cases (e.g. symlinks).
    this.allFiles = new Set(files.map(f => path.resolve(f)));
    const total = files.length;

    // Log the files to be indexed
    const relativeFiles = files.map(f => path.relative(this.workspaceRoot, f));
    console.error(`[Indexing] 📋 Discovered ${relativeFiles.length} files to index:\n` + relativeFiles.map(f => `  - ${f}`).join('\n'));

    let totalSkipped = 0;
    let lastReportedPercent = 0;

    for (let i = 0; i < total; i++) {
      const filePath = files[i];
      const success = this.analyzeFile(filePath);
      if (!success) totalSkipped++;

      if (onProgress && total > 0) {
        const percent = Math.floor(((i + 1) / total) * 100);
        const relPath = path.relative(this.workspaceRoot, filePath);
        // Report every 10% milestone to avoid log spam
        if (percent >= lastReportedPercent + 10 || percent === 100) {
          lastReportedPercent = percent;
          onProgress(percent, i + 1, total, relPath);
        }
      }
    }

    this.totalSkippedCount = totalSkipped;
    return this.buildAnalysisResult();
  }

  /**
   * Returns a copy of the uniquely tracked files as an array.
   * Note: As it is derived from a Set, duplicates are inherently avoided.
   */
  public get allFilesArray(): string[] {
    return Array.from(this.allFiles);
  }

  public async analyzeFileIncremental(filePath: string): Promise<AnalysisResult> {
    this.dirCache.clear();
    const absPath = path.resolve(filePath);

    // 1. Remove all existing nodes belonging to this file
    const nodesToRemove = new Set<string>();
    this.nodes.forEach((node, id) => {
      if (node.filePath && path.resolve(this.workspaceRoot, node.filePath) === absPath) {
        nodesToRemove.add(id);
      }
    });

    // Also remove module node matching this file's module ID
    const relativePath = path.relative(this.workspaceRoot, absPath);
    const normalizedRelativePath = relativePath.replace(/\\/g, '/');
    const moduleId = `module:${normalizedRelativePath}`;
    nodesToRemove.add(moduleId);

    nodesToRemove.forEach(id => this.nodes.delete(id));

    // 2. Remove all links associated with the removed nodes
    this.links = this.links.filter(
      link => !nodesToRemove.has(link.source) && !nodesToRemove.has(link.target)
    );

    // 3. Re-analyze only if file exists and is NOT ignored
    try {
      await fs.promises.stat(absPath);
      if (!this.isIgnored(absPath, false)) {
        const success = this.analyzeFile(absPath);
        if (success) {
          this.allFiles.add(absPath);
        } else {
          this.totalSkippedCount++;
        }
      } else {
        // File is ignored
        this.allFiles.delete(absPath);
      }
    } catch (err: unknown) {
      const error = err as NodeJS.ErrnoException;
      if (error && error.code === 'ENOENT') {
        // File was explicitly deleted or is entirely missing, remove from tracking
        this.allFiles.delete(absPath);
      } else {
        // Transient IO error or permissions issue - log it but keep it tracked
        // so it can be re-analyzed later when available, rather than silently dropping it
        this.handleFileError(err, absPath);
      }
    }

    return this.buildAnalysisResult();
  }

  private buildAnalysisResult(): AnalysisResult {
    // Calculate node degrees in O(E) instead of O(N*E) to improve buildAnalysisResult performance for large graphs
    const nodeDegrees = new Map<string, number>();
    for (const link of this.links) {
      nodeDegrees.set(link.source, (nodeDegrees.get(link.source) || 0) + 1);
      nodeDegrees.set(link.target, (nodeDegrees.get(link.target) || 0) + 1);
    }

    // Add graph layout sizes based on relationships
    this.nodes.forEach(node => {
      const degree = nodeDegrees.get(node.id) || 0;
      node.val = (node.type === 'module' ? 8 : (node.type === 'class' ? 6 : 4)) + Math.log1p(degree) * 2;
    });

    // Only keep links where both source and target nodes exist
    const validLinks = this.links.filter(
      link => this.nodes.has(link.source) && this.nodes.has(link.target)
    );

    const graph: GraphData = {
      nodes: Array.from(this.nodes.values()),
      links: validLinks
    };

    const insights = this.generateAIInsights(graph);
    const circularDepsCount = this.detectCircularDeps();

    // Calculate entity counts in a single pass over nodes instead of mapping/filtering multiple times
    let modulesCount = 0;
    let functionsCount = 0;
    let classesCount = 0;
    let variablesCount = 0;
    for (const node of this.nodes.values()) {
      if (node.type === 'module') modulesCount++;
      else if (node.type === 'function') functionsCount++;
      else if (node.type === 'class') classesCount++;
      else if (node.type === 'variable') variablesCount++;
    }

    let dependenciesCount = 0;
    for (const link of this.links) {
      if (link.type === 'import') dependenciesCount++;
    }

    const counts = {
      modules: modulesCount,
      functions: functionsCount,
      classes: classesCount,
      variables: variablesCount,
      dependencies: dependenciesCount,
      circularDeps: circularDepsCount,
      deadCode: 0
    };

    return {
      graph,
      insights,
      entityCounts: counts,
      totalFilesAnalyzed: this.allFiles.size - this.totalSkippedCount,
      totalFilesSkipped: this.totalSkippedCount
    };
  }

  /**
   * Builds chunked analysis data grouped by folder.
   * Call this after analyzeProject() to get folder-based chunks.
   */
  public buildChunkedResult(result: AnalysisResult): {
    manifest: AnalysisManifest;
    chunks: Map<string, ChunkData>;
    crossChunkLinks: CrossChunkLinks;
  } {
    // Group nodes by their parent folder
    const folderNodeMap = new Map<string, GraphNode[]>();

    for (const node of result.graph.nodes) {
      let folder = '.'; // root
      if (node.filePath) {
        const rel = path.isAbsolute(node.filePath)
          ? path.relative(this.workspaceRoot, node.filePath)
          : node.filePath;
        folder = path.dirname(rel).replace(/\\/g, '/');
      } else if (node.id.startsWith('module:')) {
        const rel = node.id.replace('module:', '');
        folder = path.dirname(rel).replace(/\\/g, '/');
      } else if (node.id.startsWith('external:')) {
        folder = '__external__';
      } else {
        // Extract folder from node id (e.g. "class:module:src/foo.ts:MyClass")
        const parts = node.id.split(':');
        if (parts.length >= 3 && parts[1] === 'module') {
          // Reconstruct the path from parts[2] (e.g. "src/foo.ts")
          folder = path.dirname(parts[2]).replace(/\\/g, '/');
        } else if (parts.length >= 2) {
          const moduleRef = parts.slice(1, -1).join(':').replace(/^module:/, '');
          if (moduleRef) {
            folder = path.dirname(moduleRef).replace(/\\/g, '/');
          }
        }
      }

      if (!folderNodeMap.has(folder)) {
        folderNodeMap.set(folder, []);
      }
      folderNodeMap.get(folder)!.push(node);
    }

    // Split large graphs into chunks for the force layout to converge faster.
    const chunks = new Map<string, ChunkData>();
    const nodeToFolder = new Map<string, string>();
    const crossLinks: GraphLink[] = [];

    // ⚡ Bolt Optimization: Initialize chunks early and map nodes to folders
    for (const [folder, nodes] of folderNodeMap) {
      for (const node of nodes) {
        nodeToFolder.set(node.id, folder);
      }
      chunks.set(folder, {
        folderPath: folder,
        nodes,
        links: []
      });
    }

    // ⚡ Bolt Optimization: Single O(L) pass to distribute links instead of O(F*L) nested filtering
    // Within-chunk links keep the layout cohesive; cross-chunk edges become thin connectors.
    for (const link of result.graph.links) {
      const srcFolder = nodeToFolder.get(link.source);
      const tgtFolder = nodeToFolder.get(link.target);
      if (srcFolder && tgtFolder) {
        if (srcFolder === tgtFolder) {
          chunks.get(srcFolder)!.links.push(link);
        } else {
          crossLinks.push(link);
        }
      }
    }

    // Manifest aggregates file-count stats per directory for the project tree.
    const folders: FolderInfo[] = [];
    for (const [folder, chunk] of chunks) {
      const types: Record<string, number> = {};
      for (const node of chunk.nodes) {
        types[node.type] = (types[node.type] || 0) + 1;
      }
      folders.push({
        path: folder,
        nodeCount: chunk.nodes.length,
        linkCount: chunk.links.length,
        types
      });
    }
    // Sort folders by node count descending for prioritized loading
    folders.sort((a, b) => b.nodeCount - a.nodeCount);

    const manifest: AnalysisManifest = {
      totalNodes: result.graph.nodes.length,
      totalLinks: result.graph.links.length,
      totalFiles: result.totalFilesAnalyzed + result.totalFilesSkipped,
      totalFilesSkipped: result.totalFilesSkipped,
      folders,
      insights: result.insights,
      entityCounts: result.entityCounts
    };

    return { manifest, chunks, crossChunkLinks: { links: crossLinks } };
  }

  /**
   * Returns the first N nodes for initial loading, picking from folders in order.
   */
  public getInitialLoadData(
    result: AnalysisResult,
    manifest: AnalysisManifest,
    chunks: Map<string, ChunkData>,
    crossChunkLinks: CrossChunkLinks,
    nodeLimit: number
  ): { graph: GraphData; loadedFolders: string[] } {
    if (nodeLimit <= 0 || nodeLimit >= result.graph.nodes.length) {
      // Load everything
      return {
        graph: result.graph,
        loadedFolders: manifest.folders.map(f => f.path)
      };
    }

    const loadedNodes: GraphNode[] = [];
    const loadedFolders: string[] = [];
    let remaining = nodeLimit;

    // Load folders by priority (sorted by nodeCount descending — most important first)
    // Actually, for better UX, sort by path alphabetically so root folders load first
    const sortedFolders = [...manifest.folders].sort((a, b) => {
      // Root folder first, then by depth, then alphabetically
      if (a.path === '.') return -1;
      if (b.path === '.') return 1;
      const depthA = a.path.split('/').length;
      const depthB = b.path.split('/').length;
      if (depthA !== depthB) return depthA - depthB;
      return a.path.localeCompare(b.path);
    });

    for (const folderInfo of sortedFolders) {
      if (remaining <= 0) break;
      const chunk = chunks.get(folderInfo.path);
      if (!chunk) continue;

      if (chunk.nodes.length <= remaining) {
        loadedNodes.push(...chunk.nodes);
        loadedFolders.push(folderInfo.path);
        remaining -= chunk.nodes.length;
      } else {
        // Partial load: take module nodes first, then classes, then functions, then variables
        const priorityOrder = ['module', 'class', 'function', 'variable'];
        const sorted = [...chunk.nodes].sort((a, b) => {
          const indexA = priorityOrder.indexOf(a.type);
          const indexB = priorityOrder.indexOf(b.type);
          // Unknown types go to the end
          const priorityA = indexA === -1 ? priorityOrder.length : indexA;
          const priorityB = indexB === -1 ? priorityOrder.length : indexB;
          return priorityA - priorityB;
        });
        loadedNodes.push(...sorted.slice(0, remaining));
        loadedFolders.push(folderInfo.path);
        remaining = 0;
      }
    }

    // Filter links to only include those where both endpoints are loaded
    const loadedNodeIds = new Set(loadedNodes.map(n => n.id));
    const loadedLinks = result.graph.links.filter(
      link => loadedNodeIds.has(link.source) && loadedNodeIds.has(link.target)
    );

    return {
      graph: { nodes: loadedNodes, links: loadedLinks },
      loadedFolders
    };
  }

  /**
   * Detects circular dependencies among modules.
   * Builds a directed graph of module imports and runs DFS cycle detection.
   * @returns {number} The total number of back-edges (cycles) found.
   */
  private detectCircularDeps(): number {
    const adjList = new Map<string, string[]>();

    // Adjacency list drives cycle detection and impact analysis.
    for (const link of this.links) {
      if (link.type === 'import' && link.source.startsWith('module:') && link.target.startsWith('module:')) {
        if (!adjList.has(link.source)) {
          adjList.set(link.source, []);
        }
        adjList.get(link.source)!.push(link.target);
      }
    }

    let cycles = 0;
    const visited = new Set<string>();
    const recStack = new Set<string>();

    const dfs = (node: string) => {
      visited.add(node);
      recStack.add(node);

      const neighbors = adjList.get(node) || [];
      for (const neighbor of neighbors) {
        if (!visited.has(neighbor)) {
          dfs(neighbor);
        } else if (recStack.has(neighbor)) {
          cycles++;
        }
      }

      recStack.delete(node);
    };

    for (const node of adjList.keys()) {
      if (!visited.has(node)) {
        dfs(node);
      }
    }

    return cycles;
  }

  private getFiles(dir: string, fileList: string[] = [], depth: number = 0): string[] {
    if (!fs.existsSync(dir)) return fileList;

    // Safety: max recursion depth = 20 levels (prevents runaway on broad paths)
    const MAX_DEPTH = 20;
    if (depth > MAX_DEPTH) {
      console.warn(`[CodeAnalyzer] Max depth (${MAX_DEPTH}) reached at ${dir}. Stopping recursion.`);
      return fileList;
    }

    // Check if current directory itself is ignored
    if (dir !== this.workspaceRoot && this.isIgnored(dir, true)) {
      return fileList;
    }

    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      return fileList;
    }

    for (const entry of entries) {
      // Keep safety check for hidden files/folders (starting with .)
      if (entry.name.startsWith('.')) {
        continue;
      }

      const filePath = path.join(dir, entry.name);

      let isDirectory = entry.isDirectory();
      if (!isDirectory && entry.isSymbolicLink()) {
        try {
          isDirectory = fs.statSync(filePath).isDirectory();
        } catch {
          continue;
        }
      }

      // Check if file/directory is ignored via .gitignore or default rules
      if (this.isIgnored(filePath, isDirectory)) {
        continue;
      }

      if (isDirectory) {
        this.getFiles(filePath, fileList, depth + 1);
      } else if (this.fileExtensions.some(ext => entry.name.endsWith(ext))) {
        fileList.push(filePath);
      }
    }

    return fileList;
  }

  private analyzeFile(filePath: string): boolean {
    let moduleId = '';
    try {
      const code = fs.readFileSync(filePath, 'utf-8');
      const relativePath = path.relative(this.workspaceRoot, filePath);
      // Normalize to use forward slashes for matching
      const normalizedRelativePath = relativePath.replace(/\\/g, '/');
      moduleId = `module:${normalizedRelativePath}`;

      const isPython = filePath.endsWith('.py');
      const isPhp = filePath.endsWith('.php') && !filePath.endsWith('.blade.php');
      const isBlade = filePath.endsWith('.blade.php');

      // Set color based on file type
      let moduleColor = '#4cc9f0'; // TS/JS default
      if (isPython) moduleColor = '#3572A5';
      else if (isPhp) moduleColor = '#4F5D95';
      else if (isBlade) moduleColor = '#FF2D20';

      this.addNode({
        id: moduleId,
        label: path.basename(filePath),
        type: 'module',
        color: moduleColor,
        filePath: filePath,
        line: 1
      });

      if (isPython) {
        this.analyzePythonFile(code, moduleId, filePath);
      } else if (isPhp) {
        this.analyzePhpFile(code, moduleId, filePath);
      } else if (isBlade) {
        this.analyzeBladeFile(code, moduleId, filePath);
      } else {
        const ast = parse(code, {
          loc: true,
          range: true,
          jsx: true
        });

        // Keep track of imports in this file to resolve calls
        const fileImports = new Map<string, string>(); // alias/name -> moduleId

        this.traverseAST(ast, moduleId, filePath, moduleId, fileImports);
      }
      return true;
    } catch (e) {
      console.warn(`Failed to parse file: ${filePath}`, e);
      // Clean up the node if it was added
      if (moduleId && this.nodes.has(moduleId)) {
        this.nodes.delete(moduleId);
      }
      return false;
    }
  }

  /**
   * Parses Python files using the PythonParser.
   */
  private analyzePythonFile(code: string, moduleId: string, filePath: string) {
    const pythonParser = new PythonParser();
    const result = pythonParser.parseFile(filePath, code);

    for (const cls of result.classes) {
      const classId = `class:${moduleId}:${cls.name}`;
      this.addNode({
        id: classId,
        label: cls.name,
        type: 'class',
        color: '#f8961e',
        filePath: filePath,
        line: cls.line
      });
      this.addLink({
        source: moduleId,
        target: classId,
        type: 'contains'
      });

      for (const parent of cls.parents) {
        const parentId = `class:${moduleId}:${parent}`;
        this.addLink({
          source: classId,
          target: parentId,
          type: 'import'
        });
      }
    }

    const reversedClasses = [...result.classes].reverse();
    for (const func of result.functions) {
      const funcId = `function:${moduleId}:${func.name}`;
      this.addNode({
        id: funcId,
        label: func.name,
        type: 'function',
        color: '#f72585',
        filePath: filePath,
        line: func.line
      });

      let linkSourceId = moduleId;
      if (typeof func.indent === 'number' && func.indent > 0 && Array.isArray(reversedClasses) && reversedClasses.length > 0) {
        // Functions without an explicit parent class are assigned to the closest
        // preceding class by line number. This handles PHP/Python file-scoped functions.
        const parentClass = binarySearchClosestPrecedingClass(
          reversedClasses as unknown as ClassReference[],
          func.line
        );
        if (parentClass) {
          linkSourceId = `class:${moduleId}:${parentClass.name}`;
        }
      }

      this.addLink({
        source: linkSourceId,
        target: funcId,
        type: 'contains'
      });
    }

    for (const variable of result.variables) {
      const varId = `variable:${moduleId}:${variable.name}`;
      this.addNode({
        id: varId,
        label: variable.name,
        type: 'variable',
        color: '#00ff88',
        filePath: filePath,
        line: variable.line
      });
      this.addLink({
        source: moduleId,
        target: varId,
        type: 'contains'
      });
    }

    for (const imp of result.imports) {
      const importPathName = imp.source || imp.names[0];
      if (!importPathName) continue;

      const resolvedModuleId = this.resolvePythonImportPath(importPathName, filePath);
      const targetId = resolvedModuleId || `external:${importPathName}`;

      this.addLink({
        source: moduleId,
        target: targetId,
        type: 'import'
      });

      if (!resolvedModuleId) {
        if (!this.nodes.has(targetId)) {
          this.addNode({
            id: targetId,
            label: importPathName,
            type: 'module',
            color: '#7209b7'
          });
        }
      }
    }

    // Scope tracker maps line ranges to class boundaries for AST pruning.
    const sortedFunctions = [...result.functions].sort((a, b) => a.line - b.line);
    for (const call of result.calls) {
      // Find which function this call is inside using binary search
      let enclosingScope = moduleId;
      let left = 0;
      let right = sortedFunctions.length - 1;
      let match = -1;

      const callLine = call.line;

      while (left <= right) {
        const mid = (left + right) >> 1;
        if (sortedFunctions[mid].line <= callLine) {
          match = mid;
          left = mid + 1;
        } else {
          right = mid - 1;
        }
      }

      if (match !== -1) {
        enclosingScope = `function:${moduleId}:${sortedFunctions[match].name}`;
      }

      const targetId = `function:${moduleId}:${call.name}`;
      // Don't add self-referencing calls
      if (enclosingScope !== targetId) {
        this.addLink({
          source: enclosingScope,
          target: targetId,
          type: 'call'
        });
      }
    }
  }

  /**
   * Parses PHP files using the PhpParser.
   */
  private analyzePhpFile(code: string, moduleId: string, filePath: string) {
    const phpParser = new PhpParser();
    const result = phpParser.parseFile(filePath, code);

    // Classes, Interfaces, Traits, Enums
    for (const cls of result.classes) {
      const nodeType = cls.type === 'interface' ? 'class' : cls.type === 'trait' ? 'class' : 'class';
      const classId = `class:${moduleId}:${cls.name}`;
      const colorMap: Record<string, string> = {
        class: '#f8961e',
        interface: '#7209b7',
        trait: '#06d6a0',
        enum: '#ffd166'
      };
      this.addNode({
        id: classId,
        label: `${cls.name}`,
        type: nodeType,
        color: colorMap[cls.type] || '#f8961e',
        filePath: filePath,
        line: cls.line
      });
      this.addLink({ source: moduleId, target: classId, type: 'contains' });

      // Extends
      for (const parent of cls.parents) {
        const parentId = `class:external:${parent}`;
        if (!this.nodes.has(parentId)) {
          this.addNode({ id: parentId, label: parent, type: 'class', color: '#f8961e' });
        }
        this.addLink({ source: classId, target: parentId, type: 'import' });
      }

      // Implements
      for (const iface of cls.implements) {
        const ifaceId = `class:external:${iface}`;
        if (!this.nodes.has(ifaceId)) {
          this.addNode({ id: ifaceId, label: iface, type: 'class', color: '#7209b7' });
        }
        this.addLink({ source: classId, target: ifaceId, type: 'import' });
      }
    }

    // Functions
    for (const func of result.functions) {
      const funcId = `function:${moduleId}:${func.name}`;
      this.addNode({
        id: funcId,
        label: func.name,
        type: 'function',
        color: '#f72585',
        filePath: filePath,
        line: func.line
      });
      this.addLink({ source: moduleId, target: funcId, type: 'contains' });
    }

    // Variables (properties, constants)
    for (const variable of result.variables) {
      const varId = `variable:${moduleId}:${variable.name}`;
      this.addNode({
        id: varId,
        label: variable.name,
        type: 'variable',
        color: '#00ff88',
        filePath: filePath,
        line: variable.line
      });
      this.addLink({ source: moduleId, target: varId, type: 'contains' });
    }

    // Use statements (imports)
    for (const imp of result.imports) {
      const importSourceId = `external:${imp.alias}`;
      this.addLink({ source: moduleId, target: importSourceId, type: 'import' });

      if (!this.nodes.has(importSourceId)) {
        this.addNode({
          id: importSourceId,
          label: imp.alias,
          type: 'module',
          color: '#7209b7'
        });
      }
    }

    // Method calls — only link to functions already discovered in the graph
    const functionNodesByName = new Map<string, string[]>();
    for (const key of this.nodes.keys()) {
      if (key.startsWith('function:')) {
        const lastColonIdx = key.lastIndexOf(':');
        if (lastColonIdx !== -1) {
          const funcName = key.substring(lastColonIdx + 1);
          let arr = functionNodesByName.get(funcName);
          if (!arr) {
            arr = [];
            functionNodesByName.set(funcName, arr);
          }
          arr.push(key);
        }
      }
    }

    for (const call of result.calls) {
      // Search all known function nodes to find a match
      const possibleTargets = functionNodesByName.get(call.name);
      if (possibleTargets && possibleTargets.length > 0) {
        this.addLink({ source: moduleId, target: possibleTargets[0], type: 'call' });
      }
    }
  }

  /**
   * Parses Blade template files to extract template relationships.
   */
  private analyzeBladeFile(code: string, moduleId: string, filePath: string) {
    const phpParser = new PhpParser();
    const result = phpParser.parseBladeFile(filePath, code);

    // @extends creates a dependency link
    for (const ext of result.extends) {
      const targetId = `blade:${ext.replace(/\./g, '/')}`;
      if (!this.nodes.has(targetId)) {
        this.addNode({ id: targetId, label: ext, type: 'module', color: '#FF2D20' });
      }
      this.addLink({ source: moduleId, target: targetId, type: 'import' });
    }

    // @include creates a dependency link
    for (const inc of result.includes) {
      const targetId = `blade:${inc.replace(/\./g, '/')}`;
      if (!this.nodes.has(targetId)) {
        this.addNode({ id: targetId, label: inc, type: 'module', color: '#FF2D20' });
      }
      this.addLink({ source: moduleId, target: targetId, type: 'import' });
    }

    // @component / <x-component>
    for (const comp of result.components) {
      const targetId = `component:${comp}`;
      if (!this.nodes.has(targetId)) {
        this.addNode({ id: targetId, label: comp, type: 'class', color: '#f8961e' });
      }
      this.addLink({ source: moduleId, target: targetId, type: 'import' });
    }
  }

  private handleImportDeclaration(node: any, currentModuleId: string, filePath: string, fileImports: Map<string, string>) {
    const importPath = node.source?.value;
    if (typeof importPath === 'string') {
      const targetModuleId = this.resolveImportPath(importPath, filePath);
      this.addLink({
        source: currentModuleId,
        target: targetModuleId,
        type: 'import'
      });

      if (node.specifiers) {
        for (const specifier of node.specifiers) {
          if (specifier.local?.name) {
            fileImports.set(specifier.local.name, targetModuleId);
          }
        }
      }

      // Ensure target module node exists (even if it's an external module for now)
      if (!this.nodes.has(targetModuleId)) {
        this.addNode({
          id: targetModuleId,
          label: importPath.split('/').pop() || importPath,
          type: 'module',
          color: '#7209b7' // external module color
        });
      }
    }
  }

  private handleFunctionDeclaration(node: any, currentModuleId: string, filePath: string, currentScopeId: string): string {
    if (node.id?.name) {
      const funcId = `function:${currentModuleId}:${node.id.name}`;
      this.addNode({
        id: funcId,
        label: node.id.name,
        type: 'function',
        color: '#f72585',
        filePath: filePath,
        line: node.loc?.start?.line
      });
      this.addLink({
        source: currentScopeId,
        target: funcId,
        type: 'contains'
      });
      return funcId;
    }
    return currentScopeId;
  }

  private handleClassDeclaration(node: any, currentModuleId: string, filePath: string, currentScopeId: string): string {
    if (node.id?.name) {
      const classId = `class:${currentModuleId}:${node.id.name}`;
      this.addNode({
        id: classId,
        label: node.id.name,
        type: 'class',
        color: '#f8961e',
        filePath: filePath,
        line: node.loc?.start?.line
      });
      this.addLink({
        source: currentScopeId,
        target: classId,
        type: 'contains'
      });
      return classId;
    }
    return currentScopeId;
  }

  private handleMethodDefinition(node: any, currentModuleId: string, filePath: string, currentScopeId: string): string {
    if (node.key?.name) {
      const methodId = `function:${currentModuleId}:${node.key.name}`;
      this.addNode({
        id: methodId,
        label: node.key.name,
        type: 'function',
        color: '#f72585',
        filePath: filePath,
        line: node.loc?.start?.line
      });
      this.addLink({
        source: currentScopeId,
        target: methodId,
        type: 'contains'
      });
      return methodId;
    }
    return currentScopeId;
  }

  private handleVariableDeclarator(node: any, currentModuleId: string, filePath: string, currentScopeId: string): string {
    if (node.id?.name) {
      const varName = node.id.name;

      if (node.init && (node.init.type === 'ArrowFunctionExpression' || node.init.type === 'FunctionExpression')) {
        const funcId = `function:${currentModuleId}:${varName}`;
        this.addNode({
          id: funcId,
          label: varName,
          type: 'function',
          color: '#f72585',
          filePath: filePath,
          line: node.loc?.start?.line
        });
        this.addLink({
          source: currentScopeId,
          target: funcId,
          type: 'contains'
        });
        return funcId;
      } else if (currentScopeId === currentModuleId) {
        // Top-level variable
        const varId = `variable:${currentModuleId}:${varName}`;
        this.addNode({
          id: varId,
          label: varName,
          type: 'variable',
          color: '#00ff88', // Green for variables
          filePath: filePath,
          line: node.loc?.start?.line
        });
        this.addLink({
          source: currentScopeId,
          target: varId,
          type: 'contains'
        });
      }
    }
    return currentScopeId;
  }

  private handleCallExpression(node: any, currentModuleId: string, currentScopeId: string, fileImports: Map<string, string>) {
    let calleeName = '';
    let objectName = '';
    if (node.callee.type === 'Identifier') {
      calleeName = node.callee.name;
    } else if (node.callee.type === 'MemberExpression' && node.callee.property?.name) {
      calleeName = node.callee.property.name;
      if (node.callee.object?.name) {
        objectName = node.callee.object.name;
      }
    }

    if (calleeName) {
      let targetId = '';
      if (objectName && fileImports.has(objectName)) {
        // It's a method call on an imported namespace/object
        const targetModule = fileImports.get(objectName);
        targetId = `function:${targetModule}:${calleeName}`;
      } else if (fileImports.has(calleeName)) {
        // It's a direct call to an imported function
        const targetModule = fileImports.get(calleeName);
        targetId = `function:${targetModule}:${calleeName}`;
      } else {
        // It's a local call
        targetId = `function:${currentModuleId}:${calleeName}`;
      }

      this.addLink({
        source: currentScopeId,
        target: targetId,
        type: 'call'
      });
    }
  }

  /**
   * Traverses the AST recursively to extract modules, functions, classes, and variables.
   * Also detects function calls and updates links.
   */
  private traverseAST(
    node: any,
    currentModuleId: string,
    filePath: string,
    currentScopeId: string,
    fileImports: Map<string, string>
  ) {
    if (!node) return;

    if (Array.isArray(node)) {
      node.forEach(child => this.traverseAST(child, currentModuleId, filePath, currentScopeId, fileImports));
      return;
    }

    let nextScopeId = currentScopeId;

    if (node.type === 'ImportDeclaration') {
      this.handleImportDeclaration(node, currentModuleId, filePath, fileImports);
    } else if (node.type === 'FunctionDeclaration') {
      nextScopeId = this.handleFunctionDeclaration(node, currentModuleId, filePath, currentScopeId);
    } else if (node.type === 'ClassDeclaration') {
      nextScopeId = this.handleClassDeclaration(node, currentModuleId, filePath, currentScopeId);
    } else if (node.type === 'MethodDefinition') {
      nextScopeId = this.handleMethodDefinition(node, currentModuleId, filePath, currentScopeId);
    } else if (node.type === 'VariableDeclarator') {
      nextScopeId = this.handleVariableDeclarator(node, currentModuleId, filePath, currentScopeId);
    } else if (node.type === 'CallExpression') {
      this.handleCallExpression(node, currentModuleId, currentScopeId, fileImports);
    }

    Object.keys(node).forEach(key => {
      if (key !== 'loc' && key !== 'range' && typeof node[key] === 'object') {
        this.traverseAST(node[key], currentModuleId, filePath, nextScopeId, fileImports);
      }
    });
  }

  /**
   * Resolves the actual module path checking for index files and standard file extensions.
   */
  private resolveImportPath(importPath: string, currentFilePath: string): string {
    if (importPath.startsWith('.')) {
      try {
        let absolutePath = path.resolve(path.dirname(currentFilePath), importPath);

        let foundPath = absolutePath;
        const extensions = this.fileExtensions;
        let matched = false;

        const dName = path.dirname(absolutePath);
        const bName = path.basename(absolutePath);
        const parentContents = this.getDirContents(dName);

        if (parentContents) {
          if (parentContents.has(bName)) {
            try {
              const entry = parentContents.get(bName);
              let isDir = entry?.isDirectory() || false;
              if (entry && !isDir && entry.isSymbolicLink()) {
                try {
                  isDir = fs.statSync(absolutePath).isDirectory();
                } catch {
                  // ignore broken symlink
                }
              }
              if (isDir) {
                const dirContents = this.getDirContents(absolutePath);
                if (dirContents) {
                  for (const ext of extensions) {
                    if (dirContents.has(`index${ext}`)) {
                      foundPath = path.join(absolutePath, `index${ext}`);
                      matched = true;
                      break;
                    }
                  }
                }
              } else {
                matched = true;
              }
            } catch (e) {
              // Ignore broken symlinks or missing files
            }
          }

          if (!matched) {
            for (const ext of extensions) {
              if (parentContents.has(`${bName}${ext}`)) {
                foundPath = `${absolutePath}${ext}`;
                matched = true;
                break;
              }
            }
          }
        }

        const relativeToWorkspace = path.relative(this.workspaceRoot, foundPath);
        // Normalize slashes
        return `module:${relativeToWorkspace.replace(/\\/g, '/')}`;
      } catch {
        return `external:${importPath}`;
      }
    }
    return `external:${importPath}`;
  }

  private resolvePythonImportPath(importPath: string, currentFilePath: string): string | null {
    let leadingDots = '';
    let rest = importPath;
    while (rest.startsWith('.')) {
      leadingDots += '.';
      rest = rest.substring(1);
    }

    let searchDirs: string[] = [];
    if (leadingDots.length > 0) {
      let targetDir = path.dirname(currentFilePath);
      for (let i = 1; i < leadingDots.length; i++) {
        targetDir = path.dirname(targetDir);
      }
      searchDirs = [targetDir];
    } else {
      searchDirs = [this.workspaceRoot, path.dirname(currentFilePath)];
    }

    const subPath = rest.replace(/\./g, '/');

    for (const baseDir of searchDirs) {
      const targetPath = path.join(baseDir, subPath);

      const dName = path.dirname(targetPath);
      const bName = path.basename(targetPath);
      const parentContents = this.getDirContents(dName);

      if (parentContents && parentContents.has(`${bName}.py`)) {
        const pyPath = `${targetPath}.py`;
        return `module:${path.relative(this.workspaceRoot, pyPath).replace(/\\/g, '/')}`;
      }

      const dirContents = this.getDirContents(targetPath);
      if (dirContents && dirContents.has('__init__.py')) {
        const initPyPath = path.join(targetPath, '__init__.py');
        return `module:${path.relative(this.workspaceRoot, initPyPath).replace(/\\/g, '/')}`;
      }
    }

    return null;
  }

  private addNode(node: GraphNode) {
    if (node.id.startsWith('external:') || node.id.includes(':external:')) {
      return;
    }
    if (node.filePath && path.isAbsolute(node.filePath)) {
      node.filePath = path.relative(this.workspaceRoot, node.filePath).replace(/\\/g, '/');
    }
    if (!this.nodes.has(node.id)) {
      this.nodes.set(node.id, node);
    }
  }

  private addLink(link: GraphLink) {
    if (
      link.source.startsWith('external:') ||
      link.target.startsWith('external:') ||
      link.source.includes(':external:') ||
      link.target.includes(':external:')
    ) {
      return;
    }
    this.links.push(link);
  }

  private generateAIInsights(graph: GraphData): AIInsight[] {
    const insights: AIInsight[] = [];

    // Mock AI Insights generation based on simple heuristics

    // Optimization: Combine multiple O(E) links traversals into a single pass
    const moduleFunctionCounts = new Map<string, number>();
    const moduleDependencies = new Map<string, number>();

    for (const l of graph.links) {
      if (l.type === 'contains' && l.target.startsWith('function')) {
        moduleFunctionCounts.set(l.source, (moduleFunctionCounts.get(l.source) || 0) + 1);
      } else if (l.type === 'import' && l.source.startsWith('module:') && l.target.startsWith('module:')) {
        moduleDependencies.set(l.source, (moduleDependencies.get(l.source) || 0) + 1);
      }
    }

    // 1. Large files / God objects
    const affectedModules: string[] = [];
    for (const node of this.nodes.values()) {
      if (node.type === 'module' && (moduleFunctionCounts.get(node.id) || 0) > 10) {
        affectedModules.push(node.id);
      }
    }

    if (affectedModules.length > 0) {
      insights.push({
        id: 'i-1',
        type: 'refactor',
        title: 'God Object Detected',
        description: `Found ${affectedModules.length} modules containing a large number of functions. Consider splitting them.`,
        severity: 'high',
        affectedNodes: affectedModules
      });
    }

    // 2. High coupling
    const highlyCoupled: string[] = [];
    for (const [id, count] of moduleDependencies.entries()) {
      if (count > 15) highlyCoupled.push(id);
    }

    if (highlyCoupled.length > 0) {
      insights.push({
        id: 'i-2',
        type: 'architecture',
        title: 'High Coupling',
        description: `Some modules have excessive external dependencies, making them hard to test.`,
        severity: 'medium',
        affectedNodes: highlyCoupled
      });
    }

    // Generic fallback insight if none found
    if (insights.length === 0) {
       insights.push({
        id: 'i-default',
        type: 'maintainability',
        title: 'Clean Architecture',
        description: 'No major structural issues detected in the analyzed scope.',
        severity: 'low',
        affectedNodes: []
      });
    }

    return insights;
  }
}

