import { parse, ASTNodeUnion, Name, Attribute } from 'py-ast';

export class PythonParser {
  public parseFile(filePath: string, code: string): {
    classes: { name: string; parents: string[]; line: number }[];
    functions: { name: string; line: number; indent?: number }[];
    variables: { name: string; line: number }[];
    imports: { source: string; names: string[]; line: number }[];
    calls: { name: string; line: number }[];
  } {
    const classes: { name: string; parents: string[]; line: number }[] = [];
    const functions: { name: string; line: number; indent?: number }[] = [];
    const variables: { name: string; line: number }[] = [];
    const imports: { source: string; names: string[]; line: number }[] = [];
    const calls: { name: string; line: number }[] = [];

    try {
      const ast = parse(code);


      const nodeToName = (baseNode: ASTNodeUnion | null | undefined): string => {
        if (!baseNode) return 'object';
        if (baseNode.nodeType === 'Name') return (baseNode as Name).id;
        if (baseNode.nodeType === 'Attribute') {
          const attrNode = baseNode as Attribute;
          return `${nodeToName(attrNode.value as ASTNodeUnion)}.${attrNode.attr}`;
        }
        if (baseNode.nodeType === 'Subscript') {
          const subNode = baseNode as Extract<ASTNodeUnion, { nodeType: 'Subscript' }>;
          return nodeToName(subNode.value as ASTNodeUnion);
        }
        return 'object';
      };

      const traverse = (node: ASTNodeUnion | null | undefined) => {
        if (!node || typeof node !== 'object') return;

        if (node.nodeType === 'ClassDef') {
          classes.push({
            name: node.name,
            parents: node.bases?.map(nodeToName) ?? [],
            line: node.lineno ?? 0
          });
        }

        if (node.nodeType === 'FunctionDef' || node.nodeType === 'AsyncFunctionDef') {
          functions.push({
            name: node.name,
            line: node.lineno ?? 0,
            indent: node.col_offset ?? 0
          });
        }

        if (node.nodeType === 'Assign') {
          node.targets?.forEach((target) => {
            if (target.nodeType === 'Name') {
              variables.push({ name: target.id, line: node.lineno ?? 0 });
            }
          });
        }

        if (node.nodeType === 'Import' || node.nodeType === 'ImportFrom') {
          imports.push({
            source: node.nodeType === 'ImportFrom' ? (node.module ?? '') : '',
            names: node.names?.map((n) => n.name) ?? [],
            line: node.lineno ?? 0
          });
        }

        if (node.nodeType === 'Call') {
          const funcNode = node.func;
          if (funcNode?.nodeType === 'Name' || funcNode?.nodeType === 'Attribute' || funcNode?.nodeType === 'Subscript') {
            calls.push({ name: nodeToName(funcNode), line: node.lineno ?? 0 });
          }
        }

        Object.values(node).forEach(child => {
          if (Array.isArray(child)) {
            child.forEach(c => traverse(c as ASTNodeUnion));
          } else if (child && typeof child === 'object') {
            traverse(child as ASTNodeUnion);
          }
        });
      };

      traverse(ast);
    } catch (e) {
      console.warn(`[PythonParser] AST parse failed for ${filePath}, using robust regex fallback.`, e);

      const lines = code.split('\n');
      let inMultilineString = false;
      let multilineQuoteChar = '';

      for (let i = 0; i < lines.length; i++) {
        let lineContent = lines[i];
        const lineNum = i + 1;

        // Handle multiline comments / strings in Python (''' or """)
        if (inMultilineString) {
          const endQuoteIdx = lineContent.indexOf(multilineQuoteChar);
          if (endQuoteIdx !== -1) {
            lineContent = lineContent.substring(endQuoteIdx + 3);
            inMultilineString = false;
          } else {
            continue; // Skip the entire line as it is inside a multiline string
          }
        }

        const tripleSingleIdx = lineContent.indexOf("'''");
        const tripleDoubleIdx = lineContent.indexOf('"""');
        if (tripleSingleIdx !== -1) {
          inMultilineString = true;
          multilineQuoteChar = "'''";
          lineContent = lineContent.substring(0, tripleSingleIdx);
        } else if (tripleDoubleIdx !== -1) {
          inMultilineString = true;
          multilineQuoteChar = '"""';
          lineContent = lineContent.substring(0, tripleDoubleIdx);
        }

        const trimmed = lineContent.trim();
        if (!trimmed || trimmed.startsWith('#')) continue;

        // Strip inline comments
        const commentIdx = lineContent.indexOf('#');
        let codePart = commentIdx !== -1 ? lineContent.substring(0, commentIdx) : lineContent;
        const codeTrimmed = codePart.trim();
        if (!codeTrimmed) continue;

        // 1. Detect Class declarations
        const classMatch = codePart.match(/^\s*class\s+([a-zA-Z0-9_]+)(?:\(([^)]+)\))?\s*:/);
        if (classMatch) {
          const className = classMatch[1];
          const parentsStr = classMatch[2] || '';
          const parents = parentsStr.split(',')
            .map(p => p.trim())
            .filter(p => p.length > 0 && !p.startsWith('*'));
          classes.push({
            name: className,
            parents: parents.length > 0 ? parents : ['object'],
            line: lineNum
          });
          continue;
        }

        // 2. Detect Function declarations
        const funcMatch = codePart.match(/^(\s*)(?:async\s+)?def\s+([a-zA-Z0-9_]+)\s*\(/);
        if (funcMatch) {
          const indentStr = funcMatch[1] || '';
          const funcName = funcMatch[2];
          functions.push({
            name: funcName,
            line: lineNum,
            indent: indentStr.length
          });
          continue;
        }

        // 3. Detect Imports
        const importFromMatch = codePart.match(/^\s*from\s+([a-zA-Z0-9_.]+)\s+import\s+(.+)$/);
        if (importFromMatch) {
          const source = importFromMatch[1];
          const namesStr = importFromMatch[2];
          const names = namesStr.split(',')
            .map(n => n.trim().split(/\s+as\s+/)[0].trim())
            .filter(n => n.length > 0 && n !== '*' && !n.startsWith('(') && !n.endsWith(')'));
          imports.push({
            source,
            names,
            line: lineNum
          });
          continue;
        }

        const importMatch = codePart.match(/^\s*import\s+(.+)$/);
        if (importMatch) {
          const namesStr = importMatch[1];
          const names = namesStr.split(',')
            .map(n => n.trim().split(/\s+as\s+/)[0].trim())
            .filter(n => n.length > 0);
          imports.push({
            source: '',
            names,
            line: lineNum
          });
          continue;
        }

        // 4. Detect Variables (Top-level uppercase constants)
        const varMatch = codePart.match(/^([A-Z_][A-Z0-9_]*)\s*=\s*/);
        if (varMatch) {
          variables.push({
            name: varMatch[1],
            line: lineNum
          });
        }

        // 5. Detect Calls
        const callRegex = /\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/g;
        let match;
        const keywords = new Set(['if', 'elif', 'while', 'for', 'def', 'class', 'with', 'assert', 'return', 'raise', 'and', 'or', 'not', 'in', 'is', 'try', 'except', 'finally']);
        while ((match = callRegex.exec(codePart)) !== null) {
          const callName = match[1];
          if (!keywords.has(callName)) {
            calls.push({
              name: callName,
              line: lineNum
            });
          }
        }
      }
    }

    return { classes, functions, variables, imports, calls };
  }
}

/**
 * PHP file parser that uses regular expressions to extract structure
 * from PHP code: classes, functions, namespaces, use statements,
 * traits, interfaces, and Blade template directives.
 */
export class PhpParser {
  private static readonly phpKeywords = new Set([
    'if', 'else', 'elseif', 'while', 'for', 'foreach', 'switch', 'case',
    'return', 'echo', 'print', 'isset', 'unset', 'empty', 'array',
    'list', 'die', 'exit', 'eval', 'include', 'require',
    'include_once', 'require_once', 'new', 'throw', 'catch', 'try',
    'finally', 'match', 'fn', 'static', 'self', 'parent'
  ]);

  /**
   * Parses PHP code to extract classes, functions, variables, imports (use), and namespace.
   */
  public parseFile(filePath: string, code: string): {
    namespace: string;
    classes: { name: string; parents: string[]; implements: string[]; type: 'class' | 'interface' | 'trait' | 'enum'; line: number }[];
    functions: { name: string; line: number }[];
    variables: { name: string; line: number }[];
    imports: { source: string; alias: string; line: number }[];
    calls: { name: string; line: number }[];
  } {
    let namespace = '';
    const classes: { name: string; parents: string[]; implements: string[]; type: 'class' | 'interface' | 'trait' | 'enum'; line: number }[] = [];
    const functions: { name: string; line: number }[] = [];
    const variables: { name: string; line: number }[] = [];
    const imports: { source: string; alias: string; line: number }[] = [];
    const calls: { name: string; line: number }[] = [];

    const lines = code.split(/\r?\n/);

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      const lineNumber = i + 1;

      // Skip comments
      if (line.startsWith('//') || line.startsWith('*') || line.startsWith('/*') || line.startsWith('#')) {
        continue;
      }

      // Namespace
      const nsMatch = /^namespace\s+([^;]+);/.exec(line);
      if (nsMatch) {
        namespace = nsMatch[1].trim();
        continue;
      }

      // Use statements (imports)
      const useMatch = /^use\s+([^;]+);/.exec(line);
      if (useMatch) {
        const useStr = useMatch[1].trim();
        // Handle "use App\Models\User as UserModel;"
        const aliasParts = useStr.split(/\s+as\s+/);
        const source = aliasParts[0].trim();
        const alias = aliasParts[1] ? aliasParts[1].trim() : source.split('\\').pop() || source;
        imports.push({ source, alias, line: lineNumber });
        continue;
      }

      // Classes, Interfaces, Traits, Enums
      const classMatch = /^(?:abstract\s+|final\s+)?(?:readonly\s+)?(class|interface|trait|enum)\s+(\w+)(?:\s+extends\s+([\w\\]+))?(?:\s+implements\s+(.+?))?(?:\s*\{|\s*$)/.exec(line);
      if (classMatch) {
        const type = classMatch[1] as 'class' | 'interface' | 'trait' | 'enum';
        const name = classMatch[2];
        const parents = classMatch[3] ? [classMatch[3].split('\\').pop() || classMatch[3]] : [];
        const implementsList = classMatch[4]
          ? classMatch[4].split(',').map(s => {
              const trimmed = s.trim();
              return trimmed.split('\\').pop() || trimmed;
            })
          : [];
        classes.push({ name, parents, implements: implementsList, type, line: lineNumber });
        continue;
      }

      // Functions and methods  
      const funcMatch = /^(?:public|protected|private|static|\s)*function\s+(\w+)\s*\(/.exec(line);
      if (funcMatch) {
        const funcName = funcMatch[1];
        if (funcName !== '__construct' && funcName !== '__destruct') {
          functions.push({ name: funcName, line: lineNumber });
        }
        continue;
      }

      // Class properties (public/protected/private $var)
      const propMatch = /^(?:public|protected|private)\s+(?:static\s+)?(?:readonly\s+)?(?:\?\w+\s+|\w+\s+)?(\$\w+)/.exec(line);
      if (propMatch) {
        variables.push({ name: propMatch[1].replace('$', ''), line: lineNumber });
        continue;
      }

      // Constants
      const constMatch = /^(?:public|protected|private)?\s*const\s+(\w+)\s*=/.exec(line);
      if (constMatch) {
        variables.push({ name: constMatch[1], line: lineNumber });
        continue;
      }

      // Static/instance method calls: ClassName::method() or $this->method()
      const callRegex = /(?:(\w+)::(\w+)|->(\w+))\s*\(/g;
      let callMatch;
      while ((callMatch = callRegex.exec(line)) !== null) {
        const callName = callMatch[2] || callMatch[3];
        if (callName && !PhpParser.phpKeywords.has(callName)) {
          calls.push({ name: callName, line: lineNumber });
        }
      }

      // Standalone function calls: func_name()
      const standaloneCallRegex = /\b(\w+)\s*\(/g;
      let scMatch;
      while ((scMatch = standaloneCallRegex.exec(line)) !== null) {
        const name = scMatch[1];
        if (!PhpParser.phpKeywords.has(name) && 
            !['function', 'class', 'interface', 'trait', 'enum', 'namespace', 'use'].includes(name) &&
            /[^a-z]/.test(name)) {
          // Only capture PascalCase or camelCase calls (likely class/method calls)
          // Optimization: Avoid .toLowerCase().replace() string allocation for regex testing
        }
      }
    }

    return { namespace, classes, functions, variables, imports, calls };
  }

  /**
   * Parses Blade template to extract directives: @extends, @include, @component, @section, @yield
   */
  public parseBladeFile(filePath: string, code: string): {
    extends: string[];
    includes: string[];
    components: string[];
    sections: string[];
    yields: string[];
  } {
    const extendsArr: string[] = [];
    const includes: string[] = [];
    const components: string[] = [];
    const sections: string[] = [];
    const yields: string[] = [];

    const lines = code.split(/\r?\n/);

    for (const line of lines) {
      // @extends('layout.app')
      const extendsMatch = /@extends\s*\(\s*['"]([^'"]+)['"]\s*\)/.exec(line);
      if (extendsMatch) extendsArr.push(extendsMatch[1]);

      // @include('partials.header')
      const includeMatch = /@include\s*\(\s*['"]([^'"]+)['"]\s*\)/.exec(line);
      if (includeMatch) includes.push(includeMatch[1]);

      // @component('components.alert') or <x-alert>
      const componentMatch = /@component\s*\(\s*['"]([^'"]+)['"]\s*\)/.exec(line);
      if (componentMatch) components.push(componentMatch[1]);

      // <x-component-name>
      const xComponentMatch = /<x-([\w.-]+)/.exec(line);
      if (xComponentMatch) components.push(xComponentMatch[1]);

      // @section('content')
      const sectionMatch = /@section\s*\(\s*['"]([^'"]+)['"]\s*\)/.exec(line);
      if (sectionMatch) sections.push(sectionMatch[1]);

      // @yield('content')
      const yieldMatch = /@yield\s*\(\s*['"]([^'"]+)['"]\s*\)/.exec(line);
      if (yieldMatch) yields.push(yieldMatch[1]);
    }

    return { extends: extendsArr, includes, components, sections, yields };
  }
}

/**
 * Finds the closest preceding class by line number using binary search.
 * Searches for the class with the highest line number that is strictly less
 * than `funcLine`. Assumes `reversedClasses` is sorted in descending order
 * based on line numbers.
 * @param reversedClasses An array of classes that MUST be sorted descending by line number.
 * @param funcLine The line number of the function to compare against.
 */
export interface ClassReference {
  name: string;
  line: number;
}

export function binarySearchClosestPrecedingClass(
  reversedClasses: ClassReference[],
  funcLine: number
): ClassReference | undefined {
  if (!Array.isArray(reversedClasses) || reversedClasses.length === 0) return undefined;

  let startIdx = 0;
  let endIdx = reversedClasses.length - 1;
  let parentClass = undefined;

  while (startIdx <= endIdx) {
    // Unsigned right shift (>>> 1) efficiently computes Math.floor((startIdx + endIdx) / 2)
    // while protecting against potential 32-bit integer overflow.
    const middleIdx = (startIdx + endIdx) >>> 1;
    if (reversedClasses[middleIdx] && typeof reversedClasses[middleIdx].line === 'number' && reversedClasses[middleIdx].line < funcLine) {
      parentClass = reversedClasses[middleIdx];
      endIdx = middleIdx - 1;
    } else {
      startIdx = middleIdx + 1;
    }
  }
  return parentClass;
}

import { expand } from 'brace-expansion'
import { assertValidPattern } from './assert-valid-pattern.js'
import type { ExtglobType } from './ast.js'
import { AST } from './ast.js'
import { escape } from './escape.js'
import { unescape } from './unescape.js'

export type Platform =
  | 'aix'
  | 'android'
  | 'darwin'
  | 'freebsd'
  | 'haiku'
  | 'linux'
  | 'openbsd'
  | 'sunos'
  | 'win32'
  | 'cygwin'
  | 'netbsd'

export interface MinimatchOptions {
  /** do not expand `{x,y}` style braces */
  nobrace?: boolean
  /** do not treat patterns starting with `#` as a comment */
  nocomment?: boolean
  /** do not treat patterns starting with `!` as a negation */
  nonegate?: boolean
  /** print LOTS of debugging output */
  debug?: boolean
  /** treat `**` the same as `*` */
  noglobstar?: boolean
  /** do not expand extglobs like `+(a|b)` */
  noext?: boolean
  /** return the pattern if nothing matches */
  nonull?: boolean
  /** treat `\\` as a path separator, not an escape character */
  windowsPathsNoEscape?: boolean
  /**
   * inverse of {@link MinimatchOptions.windowsPathsNoEscape}
   * @deprecated
   */
  allowWindowsEscape?: boolean
  /**
   * Compare a partial path to a pattern. As long as the parts
   * of the path that are present are not contradicted by the
   * pattern, it will be treated as a match. This is useful in
   * applications where you're walking through a folder structure,
   * and don't yet have the full path, but want to ensure that you
   * do not walk down paths that can never be a match.
   */
  partial?: boolean
  /** allow matches that start with `.` even if the pattern does not */
  dot?: boolean
  /** ignore case */
  nocase?: boolean
  /** ignore case only in wildcard patterns */
  nocaseMagicOnly?: boolean
  /** consider braces to be "magic" for the purpose of `hasMagic` */
  magicalBraces?: boolean
  /**
   * If set, then patterns without slashes will be matched
   * against the basename of the path if it contains slashes.
   * For example, `a?b` would match the path `/xyz/123/acb`, but
   * not `/xyz/acb/123`.
   */
  matchBase?: boolean
  /** invert the results of negated matches */
  flipNegate?: boolean
  /** do not collapse multiple `/` into a single `/` */
  preserveMultipleSlashes?: boolean
  /**
   * A number indicating the level of optimization that should be done
   * to the pattern prior to parsing and using it for matches.
   */
  optimizationLevel?: number
  /** operating system platform */
  platform?: Platform
  /**
   * When a pattern starts with a UNC path or drive letter, and in
   * `nocase:true` mode, do not convert the root portions of the
   * pattern into a case-insensitive regular expression, and instead
   * leave them as strings.
   *
   * This is the default when the platform is `win32` and
   * `nocase:true` is set.
   */
  windowsNoMagicRoot?: boolean
  /**
   * max number of `{...}` patterns to expand. Default 100_000.
   */
  braceExpandMax?: number
  /**
   * Max number of non-adjacent `**` patterns to recursively walk down.
   *
   * The default of 200 is almost certainly high enough for most purposes,
   * and can handle absurdly excessive patterns.
   */
  maxGlobstarRecursion?: number

  /**
   * Max depth to traverse for nested extglobs like `*(a|b|c)`
   *
   * Default is 2, which is quite low, but any higher value
   * swiftly results in punishing performance impacts. Note
   * that this is *not*  relevant when the globstar types can
   * be safely coalesced into a single set.
   *
   * For example, `*(a|@(b|c)|d)` would be flattened into
   * `*(a|b|c|d)`. Thus, many common extglobs will retain good
   * performance and  never hit this limit, even if they are
   * excessively deep and complicated.
   *
   * If the limit is hit, then the extglob characters are simply
   * not parsed, and the pattern effectively switches into
   * `noextglob: true` mode for the contents of that nested
   * sub-pattern. This will typically _not_ result in a match,
   * but is considered a valid trade-off for security and
   * performance.
   */
  maxExtglobRecursion?: number
}

export const minimatch = (
  p: string,
  pattern: string,
  options: MinimatchOptions = {},
) => {
  assertValidPattern(pattern)

  // shortcut: comments match nothing.
  if (!options.nocomment && pattern.charAt(0) === '#') {
    return false
  }

  return new Minimatch(pattern, options).match(p)
}

