      }
      return sawTail
    }

    // have a non-globstar body section to test
    const [body, after] = bs
    while (fileIndex <= after) {
      const m = this.#matchOne(
        file.slice(0, fileIndex + body.length),
        body,
        partial,
        fileIndex,
        0,
